use std::{fs::OpenOptions, io::Write};

use anyhow::Result;

use crate::debug;

pub trait ContinuousIntegration {
    /// A function for returning the value for an input by the given name.
    fn get_input(&self, name: &str) -> Option<String>;

    /// Refers to the GITHUB_ENV concept in GitHub Actions. Sets a name and value pair to the environment
    fn set_environment(&mut self, name: &str, value: &str) -> Result<()>;

    /// Refers to the GITHUB_OUTPUT concept in GitHub Actions. Sets secrets to this output file.
    fn set_output(&mut self, name: &str, value: &str) -> Result<()>;

    /// Masks a value in the CI logs to prevent it from being displayed.
    /// In some CI systems this may not be possible. In which case this function may be a no-op.
    fn mask_value(&mut self, value: &str);
}

pub struct GithubActionsRunner<W: Write> {
    env_file: W,
    output_file: W,
}

impl<W: Write> GithubActionsRunner<W> {
    fn issue_file_command(file: &mut W, key: &str, value: &str) -> Result<()> {
        let delimiter = format!("ghadelimiter_{}", uuid::Uuid::new_v4());
        writeln!(file, "{key}<<{delimiter}")?;
        writeln!(file, "{value}")?;
        writeln!(file, "{delimiter}")?;
        file.flush()?; // ensure the data is written to disk
        Ok(())
    }

    /// Prefer this over `std::env::var` to ensure that vars are both set and not empty to avoid
    /// unintended errors.
    fn get_var(key: &str) -> Option<String> {
        match std::env::var(key) {
            Ok(value) if !value.trim().is_empty() => Some(value),
            _ => None,
        }
    }

    fn escape_secret(&self, value: &str) -> String {
        value
            .replace('%', "%25")
            .replace('\r', "%0D")
            .replace('\n', "%0A")
    }
}

impl GithubActionsRunner<std::fs::File> {
    pub fn new() -> Result<GithubActionsRunner<std::fs::File>> {
        let env_path = std::env::var("GITHUB_ENV").expect("GITHUB_ENV must be set");

        debug!("Writing to GITHUB_ENV: {env_path}");

        let env_file = OpenOptions::new().append(true).open(&env_path)?;

        let output_path = std::env::var("GITHUB_OUTPUT").expect("GITHUB_OUTPUT must be set");

        debug!("Writing to GITHUB_OUTPUT: {env_path}");

        let output_file = OpenOptions::new().append(true).open(&output_path)?;
        Ok(Self {
            env_file,
            output_file,
        })
    }
}

impl<W: Write> ContinuousIntegration for GithubActionsRunner<W> {
    fn get_input(&self, name: &str) -> Option<String> {
        let upper_name = name.to_ascii_uppercase();
        Self::get_var(&format!("INPUT_{upper_name}")).to_owned()
    }

    fn set_environment(&mut self, name: &str, value: &str) -> Result<()> {
        Self::issue_file_command(&mut self.env_file, name, value)
    }

    fn set_output(&mut self, name: &str, value: &str) -> Result<()> {
        Self::issue_file_command(&mut self.output_file, name, value)
    }

    /// Masks a value in the GitHub Actions logs to prevent it from being displayed.
    fn mask_value(&mut self, value: &str) {
        let escaped_secret = [REDACTED], value);
        println!("::add-mask::{escaped_secret}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_gh_stuff() -> Result<()> {
        let env_buf = vec![];
        let output_buf = vec![];

        let mut gh: GithubActionsRunner<Vec<_>> = GithubActionsRunner {
            env_file: env_buf,
            output_file: output_buf,
        };

        let _ = gh.set_output("NAME1", "VALUE1");
        let _ = gh.set_output("NAME2", "VALUE2\nNEWLINE");
        let _ = gh.set_output("NAME3", "\nVALUE3\n\t\t\t\tNEWLINE");

        let binding = gh.output_file;

        let (value_1, delimiter_value_1) = assert_github_output(&binding, "NAME1")?;
        let (value_2, delimiter_value_2) = assert_github_output(&binding, "NAME2")?;
        let (value_3, delimiter_value_3) = assert_github_output(&binding, "NAME3")?;

        assert_eq!(value_1, "VALUE1");
        assert_eq!(value_2, "VALUE2\nNEWLINE");
        assert_eq!(value_3, "\nVALUE3\n\t\t\t\tNEWLINE");
        assert_ne!(delimiter_value_1, delimiter_value_2);
        assert_ne!(delimiter_value_2, delimiter_value_3);
        Ok(())
    }

    #[test]
    fn test_multiline_secret_masking() {
        let gh: GithubActionsRunner<Vec<u8>> = GithubActionsRunner {
            env_file: vec![],
            output_file: vec![],
        };

        let multiline_secret = "-----BEGIN TEST KEY-----
AAAA_THIS_IS_LINE_TWO_SENSITIVE
BBBB_THIS_IS_LINE_THREE_SENSITIVE
-----END TEST KEY-----";

        let escaped = gh.escape_secret(multiline_secret);

        assert!(
            escaped.contains("AAAA_THIS_IS_LINE_TWO_SENSITIVE"),
            "Second line should be present in escaped value"
        );
        assert!(
            escaped.contains("BBBB_THIS_IS_LINE_THREE_SENSITIVE"),
            "Third line should be present in escaped value"
        );
        assert!(
            escaped.contains("-----BEGIN TEST KEY-----"),
            "First line should be present in escaped value"
        );
        assert!(
            escaped.contains("-----END TEST KEY-----"),
            "Fourth line should be present in escaped value"
        );
        assert!(
            !escaped.contains('\n'),
            "No raw newlines should remain after escaping"
        );
        assert!(escaped.contains("%0A"), "Newlines should be escaped as %0A");
    }

    #[test]
    fn test_escape_characters() {
        let gh: GithubActionsRunner<Vec<u8>> = GithubActionsRunner {
            env_file: vec![],
            output_file: vec![],
        };

        let value_with_escapes = "100% complete\r\nline2";

        let escaped = gh.escape_secret(value_with_escapes);

        assert!(
            escaped.contains("%25"),
            "Percent signs should be escaped as %25"
        );
        assert!(
            escaped.contains("%0D"),
            "Carriage returns should be escaped as %0D"
        );
        assert!(escaped.contains("%0A"), "Newlines should be escaped as %0A");
        assert!(
            escaped.contains("100"),
            "Original content should be preserved"
        );
        assert!(
            escaped.contains("complete"),
            "Original content should be preserved"
        );
        assert!(
            escaped.contains("line2"),
            "Original content should be preserved"
        );
    }

    /// Asserts that name value pairs are written to the buffer in the correct format
    fn assert_github_output(buffer: &[u8], name: &str) -> Result<(String, uuid::Uuid)> {
        let delimiter_marker = "<<";
        let ghadelimiter_prefix = "ghadelimiter_";
        // Convert the byte buffer to a UTF-8 string and search its lines for the matching prefix.
        let binding = String::from_utf8(buffer.to_vec()).expect("buffer is valid UTF-8");
        let lines = binding.lines().collect::<Vec<&str>>();

        // Find the line that begins with the desired value and return the index it was found at
        let matching_line = lines
            .iter()
            .enumerate()
            .find(|l| {
                l.1.starts_with(&format!("{name}{delimiter_marker}{ghadelimiter_prefix}"))
            })
            .unwrap();

        // Parse the UUID out of the first line
        let delimiter = uuid::Uuid::parse_str(
            matching_line
                .1
                .chars()
                .skip(name.len() + delimiter_marker.len() + ghadelimiter_prefix.len())
                .collect::<String>()
                .as_ref(),
        )?;

        // Find the line number for the end of this value, our secret value should be everything
        // between the start and end
        let end_delimiter_line = lines
            .iter()
            .enumerate()
            .find(|l| l.1 == &format!("{ghadelimiter_prefix}{delimiter}"))
            .map(|l| l.0)
            .unwrap();

        // The line below the line with our delimiter and name should house the value
        // If the value is multiline then this could span multiple lines
        let value = lines
            .get(matching_line.0 + 1..end_delimiter_line)
            .unwrap()
            .join("\n");

        Ok((value, delimiter))
    }
}

const { execSync } = require("node:child_process");
const fs = require("fs");
const path = require("path");
const https = require("https");
const version = require("./version.json").version;

const repoOwner = "bitwarden";
const repoName = "sm-action";

function debug(message) {
  if ("RUNNER_DEBUG" in process.env || "ACTIONS_RUNNER_DEBUG" in process.env) {
    console.log(`::debug::${message}`);
  }
}

function getVersion() {
  if ("SM_ACTION_VERSION" in process.env) {
    console.log(
      `Using version from environment: ${process.env.SM_ACTION_VERSION}`,
    );
    return process.env.SM_ACTION_VERSION;
  }

  console.log(`Using version from version.json: ${version}`);
  return version;
}

function ensureDirectoryExists(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function safeUnlink(filePath) {
  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
}

function cleanupDownload(file, request, outputPath) {
  file.close();
  safeUnlink(outputPath);
  request.destroy();
}

/**
 * Downloads a file from a URL to a local path
 */
function downloadFile(url, outputPath) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(outputPath);

    const request = https.get(url, (response) => {
      // Handle redirects
      if (response.statusCode === 302 || response.statusCode === 301) {
        cleanupDownload(file, request, outputPath);
        return downloadFile(response.headers.location, outputPath)
          .then(resolve)
          .catch(reject);
      }

      // Handle non-success status codes
      if (response.statusCode !== 200) {
        cleanupDownload(file, request, outputPath);
        return reject(
          new Error(
            `Failed to download: ${response.statusCode} ${response.statusMessage}`,
          ),
        );
      }

      // Pipe response to file
      response.pipe(file);

      // Handle successful completion
      file.on("finish", () => {
        file.close();
        request.destroy();
        resolve();
      });

      // Handle file write errors
      file.on("error", (err) => {
        cleanupDownload(file, request, outputPath);
        reject(err);
      });
    });

    // Handle request errors
    request.on("error", (err) => {
      cleanupDownload(file, request, outputPath);
      reject(err);
    });

    // Set timeout to prevent hanging
    request.setTimeout(30000, () => {
      cleanupDownload(file, request, outputPath);
      reject(new Error("Download timeout"));
    });
  });
}

/**
 * Constructs the GitHub release download URL
 */
function buildDownloadUrl(targetTriple, version) {
  const releaseVersion = `${version}`;
  const assetName = `sm-action-${targetTriple}${
    process.platform === "win32" ? ".exe" : ""
  }`;

  return `https://github.com/${repoOwner}/${repoName}/releases/download/v${releaseVersion}/${assetName}`;
}

/**
 * Attempts to download the pre-built binary from GitHub Releases
 */
async function downloadBinary(targetTriple, binaryPath) {
  const version = getVersion();
  const downloadUrl = buildDownloadUrl(targetTriple, version);

  console.log(`Attempting to download binary from: ${downloadUrl}`);

  try {
    ensureDirectoryExists(path.dirname(binaryPath));
    await downloadFile(downloadUrl, binaryPath);
    console.log(`Successfully downloaded binary to: ${binaryPath}`);
    return true;
  } catch (error) {
    console.warn(`Failed to download binary: ${error.message}`);
    return false;
  }
}

function getArch() {
  const archMap = {
    x64: "x86_64",
    arm64: "aarch64",
  };

  const arch = archMap[process.arch];
  if (arch == null) {
    throw new Error(`Unsupported architecture: ${process.arch}`);
  }

  return arch;
}

function getPlatform() {
  const platformMap = {
    linux: "unknown-linux-gnu",
    darwin: "apple-darwin",
    win32: "pc-windows-msvc",
  };

  const platform = platformMap[process.platform];
  if (platform == null) {
    throw new Error(`Unsupported platform: ${process.platform}`);
  }

  return platform;
}

function getTargetTriple() {
  return `${getArch()}-${getPlatform()}`;
}

function getBinaryName() {
  return process.platform === "win32" ? "sm-action.exe" : "sm-action";
}

async function buildFromSource(targetTriple) {
  const buildTarget = targetTriple.includes("linux")
    ? `${getArch()}-unknown-linux-gnu`
    : targetTriple;

  // Check if target is installed
  const installedTargets = execSync(
    "rustup target list --installed",
  ).toString();

  if (!installedTargets.includes(buildTarget)) {
    console.log(`Installing Rust target: ${buildTarget}`);
    execSync(`rustup target add ${buildTarget}`, { stdio: "inherit" });
  }

  console.log(`Building binary for target: ${buildTarget}`);
  execSync(`cargo build --release --target ${buildTarget}`, {
    stdio: "inherit",
  });
}

function copyBuiltBinary(targetTriple, binaryName, expectedPath) {
  const builtBinaryPath = path.join(
    __dirname,
    "target",
    targetTriple,
    "release",
    binaryName,
  );

  if (!fs.existsSync(builtBinaryPath)) {
    throw new Error(`Failed to build binary at ${builtBinaryPath}`);
  }

  ensureDirectoryExists(path.dirname(expectedPath));
  fs.copyFileSync(builtBinaryPath, expectedPath);
}

async function getBinary() {
  const targetTriple = getTargetTriple();
  const binaryName = getBinaryName();
  const binaryPath = path.join(
    __dirname,
    "target",
    targetTriple,
    "release",
    binaryName,
  );

  debug(`Looking for binary at: ${binaryPath}`);

  if (fs.existsSync(binaryPath)) {
    return binaryPath;
  }

  debug(`No sm-action binary found for target: ${targetTriple}`);

  const downloadSuccess = await downloadBinary(targetTriple, binaryPath);

  if (downloadSuccess) {
    return binaryPath;
  }

  console.log("sm-action binary download failed. Building from source...");
  await buildFromSource(targetTriple);
  copyBuiltBinary(targetTriple, binaryName, binaryPath);

  return binaryPath;
}

function makeExecutable(binaryPath) {
  if (process.platform !== "win32") {
    fs.chmodSync(binaryPath, 0o755);
  }
}

async function run() {
  try {
    const binaryPath = await getBinary();
    makeExecutable(binaryPath);
    execSync(binaryPath, { stdio: "inherit" });
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }
}

run();

use std::collections::HashMap;
use std::str::FromStr;

use anyhow::Result;
use bitwarden::{
    Client, ClientSettings, DeviceType, auth::login::AccessTokenLoginRequest,
    secrets_manager::secrets::SecretsGetRequest,
};
use config::{Config, infer_urls};
use uuid::Uuid;

use ci::{ContinuousIntegration, GithubActionsRunner};

mod ci;
mod config;

const VERSION: &str = env!("CARGO_PKG_VERSION");

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    let mut github_runner = GithubActionsRunner::new()?;
    run(&mut github_runner).await
}

async fn run<T: ContinuousIntegration>(ci: &mut T) -> Result<()> {
    // this doubles as a way to validate the binaries in CI
    if std::env::args().any(|arg| arg == "--version") {
        println!("{VERSION}");
        return Ok(());
    }

    let config = Config::new(ci)?;
    let (api_url, identity_url) = infer_urls(&config)?;

    let client = Client::new(Some(ClientSettings {
        identity_url,
        api_url,
        user_agent: "bitwarden/sm-action".to_string(),
        device_type: DeviceType::SDK,
        ..Default::default()
    }));

    println!("Parsing secrets input...");
    let id_to_name_map = parse_secret_input(config.secrets).map_err(|_| {
        anyhow::anyhow!("Failed to parse secrets input. Ensure the format is 'UUID > Name'.")
    })?;

    println!("Authenticating with Bitwarden...");
    let auth_result = client
        .auth()
        .login_access_token(&AccessTokenLoginRequest {
            access_token: [REDACTED],
            state_file: None,
        })
        .await;

    if let Err(e) = auth_result {
        return Err(anyhow::anyhow!(
            "Authentication with Bitwarden failed.\nError: {e}",
        ));
    }

    let secret_ids: Vec<Uuid> = id_to_name_map.keys().cloned().collect();

    let secrets = client
        .secrets()
        .get_by_ids(SecretsGetRequest { ids: secret_ids })
        .await.map_err(|e| {
            anyhow::anyhow!(
                "The secrets provided could not be found. Please check the machine account has access to the secret UUIDs provided.\nError: {e}",
            )
        })?;

    println!("Setting secrets...");
    for secret in secrets.data.iter() {
        id_to_name_map
            .get(&secret.id)
            .map(|name| set_secret(ci, name, &secret.value, config.set_env))
            .transpose()?;
    }

    println!("Completed setting secrets.");

    Ok(())
}

/// Parses the secret input from the GitHub Actions environment variable.
fn parse_secret_input(secret_lines: Vec<String>) -> Result<HashMap<Uuid, String>> {
    let mut map: HashMap<Uuid, String> = HashMap::with_capacity(secret_lines.capacity());

    for line in secret_lines.iter() {
        debug!("Parsing line: {line}");
        let uuid_part = line.split('>').next().unwrap_or_default().trim();
        let uuid = Uuid::from_str(uuid_part)
            .map_err(|_| anyhow::anyhow!("Invalid UUID format: {uuid_part}"))?;

        let desired_name = line.split('>').nth(1).unwrap_or_default().trim();

        if let Some(old_value) = map.insert(uuid, desired_name.to_string()) {
            eprintln!(
                "Warning: Duplicate UUID found: {uuid}. Old value: {old_value}, New value: {desired_name}"
            );
        }
    }

    Ok(map)
}

/// Sets a secret in the GitHub Actions environment.
fn set_secret<T: ContinuousIntegration>(
    ci: &mut T,
    secret_name: &str,
    secret_value: &str,
    set_env: bool,
) -> Result<()> {
    ci.mask_value(secret_value);

    if set_env {
        ci.set_environment(secret_name, secret_value)?;
        debug!("Successfully wrote '{secret_name}' to environment");
    }

    ci.set_output(secret_name, secret_value)?;
    debug!("Successfully wrote '{secret_name}' to output file");

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    struct FakeContinuousIntegration {
        inputs: HashMap<String, String>,
        outputs: HashMap<String, String>,
        environment: HashMap<String, String>,
        masked_values: Vec<String>,
    }

    impl FakeContinuousIntegration {
        fn new(inputs: HashMap<String, String>) -> Self {
            FakeContinuousIntegration {
                inputs,
                outputs: HashMap::new(),
                environment: HashMap::new(),
                masked_values: Vec::new(),
            }
        }

        fn default() -> Self {
            Self::new(HashMap::default())
        }
    }

    impl ContinuousIntegration for FakeContinuousIntegration {
        fn get_input(&self, value: &str) -> Option<String> {
            self.inputs.get(value).map(|s| s.to_owned())
        }

        fn set_environment(&mut self, name: &str, value: &str) -> Result<()> {
            self.environment.insert(name.to_owned(), value.to_owned());
            Ok(())
        }

        fn set_output(&mut self, name: &str, value: &str) -> Result<()> {
            self.outputs.insert(name.to_owned(), value.to_owned());
            Ok(())
        }

        fn mask_value(&mut self, value: &str) {
            self.masked_values.push(value.to_owned());
        }
    }

    #[test]
    fn test_set_secrets() {
        let secret_name = "TEST_SECRET";
        let secret_value = r#"BrowserSettings__EnvironmentUrl=https://example.com

    # Browser Settings 2
    BrowserSettings__EnvironmentUrl=https://example2.com"#;

        let mut ci = FakeContinuousIntegration::default();

        // Run the function
        set_secret(&mut ci, secret_name, secret_value, true).unwrap();

        assert_eq!(
            ci.environment.get(secret_name),
            Some(&secret_value.to_string())
        );
        assert_eq!(ci.outputs.get(secret_name), Some(&secret_value.to_string()));
    }

    #[test]
    fn test_set_secrets_with_set_env_disabled() {
        let secret_name = "TEST_SECRET";
        let secret_value = r#"BrowserSettings__EnvironmentUrl=https://example.com

    # Browser Settings 2
    BrowserSettings__EnvironmentUrl=https://example2.com"#;

        let mut ci = FakeContinuousIntegration::default();

        // Run the function
        set_secret(&mut ci, secret_name, secret_value, false).unwrap();

        // Check if GITHUB_OUTPUT was created and contains the expected values

        assert_eq!(ci.environment.get(secret_name), None);
        assert_eq!(ci.outputs.get(secret_name), Some(&secret_value.to_string()));
    }

    #[test]
    fn test_parse_secret_lines() {
        let id_to_name_map = parse_secret_input(vec![
            "91ba3f10-a9a2-4795-bacf-0eee2d39a074 > ONE".to_string(),
            "bfd7aa33-54f2-487b-bbbf-4a69b49fdc0d > TWO".to_string(),
        ])
        .unwrap();

        assert_eq!(id_to_name_map.len(), 2);
        assert_eq!(
            id_to_name_map.get(&Uuid::from_str("91ba3f10-a9a2-4795-bacf-0eee2d39a074").unwrap()),
            Some(&"ONE".to_string())
        );

        assert_eq!(
            id_to_name_map.get(&Uuid::from_str("bfd7aa33-54f2-487b-bbbf-4a69b49fdc0d").unwrap()),
            Some(&"TWO".to_string())
        );
    }

    #[test]
    fn test_parse_secret_lines_two() {
        let id_to_name_map = parse_secret_input(vec![
            "91ba3f10-a9a2-4795-bacf-0eee2d39a074 > ONE".to_string(),
            "91ba3f10-a9a2-4795-bacf-0eee2d39a074 > TWO".to_string(),
        ])
        .unwrap();

        assert_eq!(id_to_name_map.len(), 1); // We expect only one entry since the UUID is the same

        assert_eq!(
            id_to_name_map.get(&Uuid::from_str("91ba3f10-a9a2-4795-bacf-0eee2d39a074").unwrap()),
            Some(&"TWO".to_string())
        );
    }

    #[test]
    fn test_parse_secret_lines_invalid_uuid() {
        let id_to_name_map = parse_secret_input(vec![
            "invalid-uuid > INVALID".to_string(),
            "91ba3f10-a9a2-4795-bacf-0eee2d39a074 > VALID".to_string(),
        ]);

        assert!(id_to_name_map.is_err());
    }
}

use anyhow::{Result, bail};

use crate::ci::ContinuousIntegration;

/// Prints a debug message to the GitHub Actions log if `RUNNER_DEBUG` or `ACTIONS_RUNNER_DEBUG` are set.
#[macro_export]
macro_rules! debug {
    ($($arg:tt)*) => {
        if std::env::var("RUNNER_DEBUG").is_ok() || std::env::var("ACTIONS_RUNNER_DEBUG").is_ok() {
            println!("::debug::{}", format!($($arg)*));
        }
    };
}

const EU_DEFAULT_API_URL: &str = "https://api.bitwarden.eu";
const EU_DEFAULT_IDENTITY_URL: &str = "https://identity.bitwarden.eu";

const US_DEFAULT_API_URL: &str = "https://api.bitwarden.com";
const US_DEFAULT_IDENTITY_URL: &str = "https://identity.bitwarden.com";

#[derive(Debug, PartialEq)]
pub enum EnvironmentType {
    Eu,
    Us,
    Other, // unrecognized; treat it as self-hosted
}

impl EnvironmentType {
    fn from_str(input: &str) -> Self {
        match input.trim().to_ascii_lowercase().as_ref() {
            "us" => EnvironmentType::Us,
            "eu" => EnvironmentType::Eu,
            _ => EnvironmentType::Other,
        }
    }
}

#[derive(Debug)]
/// Input parameters for the GitHub Action.
pub struct Config {
    pub access_token: String,
    pub secrets: Vec<String>,
    pub cloud_region: EnvironmentType,
    pub base_url: Option<String>,
    pub api_url: Option<String>,
    pub identity_url: Option<String>,
    pub set_env: bool,
}

impl Config {
    /// Creates a new Config instance from environment variables.
    pub fn new<T: ContinuousIntegration>(ci: &T) -> Result<Self> {
        let cloud_region =
            EnvironmentType::from_str(&ci.get_input("CLOUD_REGION").unwrap_or_default());

        let access_token = ci
            .get_input("ACCESS_TOKEN")
            .ok_or_else(|| anyhow::anyhow!("Access token is required"))?;

        let secrets = ci
            .get_input("SECRETS")
            .ok_or_else(|| anyhow::anyhow!("Secrets are required"))?
            .lines()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(String::from)
            .collect();

        let base_url = ci.get_input("BASE_URL");
        let api_url = ci.get_input("API_URL");
        let identity_url = ci.get_input("IDENTITY_URL");

        debug!("cloud_region: {cloud_region:?}");
        debug!("secrets:      {secrets:?}");
        debug!("base_url:     {base_url:?}");
        debug!("api_url:      {api_url:?}");
        debug!("identity_url: {identity_url:?}");

        validate_urls(
            base_url.as_deref(),
            api_url.as_deref(),
            identity_url.as_deref(),
        )?;

        let set_env = ci
            .get_input("SET_ENV")
            .is_some_and(|val| !val.eq_ignore_ascii_case("false"));
        debug!("set_env: {set_env}");

        Ok(Self {
            access_token,
            secrets,
            cloud_region,
            base_url,
            api_url,
            identity_url,
            set_env,
        })
    }
}

fn validate_urls(
    base_url: Option<&str>,
    api_url: Option<&str>,
    identity_url: Option<&str>,
) -> Result<()> {
    if base_url.is_none() && api_url.is_none() && identity_url.is_none() {
        return Ok(()); // No URLs provided, nothing to validate
    }

    if let Some(url) = base_url
        && !url.starts_with("http://")
        && !url.starts_with("https://")
    {
        bail!("base_url must start with 'https://' or 'http://'");
    }

    if let Some(url) = api_url
        && !url.starts_with("http://")
        && !url.starts_with("https://")
    {
        bail!("api_url must start with 'https://' or 'http://'");
    }

    if let Some(url) = identity_url
        && !url.starts_with("http://")
        && !url.starts_with("https://")
    {
        bail!("identity_url must start with 'https://' or 'http://'");
    }

    Ok(())
}

/// Infers the API and Identity URLs based on the base URL or defaults.
/// If none of these values are set, it defaults to US or EU URLs,
/// with US being preferred.
pub fn infer_urls(config: &Config) -> Result<(String, String)> {
    match config.cloud_region {
        // A cloud region was specified; use it
        EnvironmentType::Eu => {
            debug!("Using EU cloud region URLs");
            Ok((
                EU_DEFAULT_API_URL.to_string(),
                EU_DEFAULT_IDENTITY_URL.to_string(),
            ))
        }
        EnvironmentType::Us => {
            debug!("Using US cloud region URLs");
            Ok((
                US_DEFAULT_API_URL.to_string(),
                US_DEFAULT_IDENTITY_URL.to_string(),
            ))
        }

        // A cloud region was not detected; fall back to inferring the URLs
        EnvironmentType::Other => {
            debug!("No cloud region detected; inferring URLs");

            match (config.api_url.clone(), config.identity_url.clone()) {
                // API and Identity were provided; use them
                (Some(api), Some(identity)) => {
                    debug!("Using provided API and Identity URLs");
                    Ok((api, identity))
                }

                // Only API was provided; this is an error
                (Some(_), None) => {
                    bail!("Both API and Identity URLs must be provided if one is specified");
                }

                // Only Identity was provided; this is an error
                (None, Some(_)) => {
                    bail!("Both API and Identity URLs must be provided if one is specified");
                }

                // Neither API nor Identity were provided; use the base URL
                (None, None) => match config.base_url.clone() {
                    // Infer the API and Identity URLs from the base URL
                    Some(base) => {
                        debug!("Using provided Base URL");
                        Ok((format!("{base}/api"), format!("{base}/identity")))
                    }

                    // No URLs were provided; use the defaults
                    None => {
                        debug!("Using default URLs");
                        Ok((
                            US_DEFAULT_API_URL.to_string(),
                            US_DEFAULT_IDENTITY_URL.to_string(),
                        ))
                    }
                },
            }
        }
    }
}

